        n = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if (r + dr, c + dc) in self.alive:
                    n += 1
        return n

"""One generation of Conway's rules.

A live cell with 2 or 3 live neighbours survives; a dead cell with exactly 3 becomes alive; all
other cells are dead in the next generation.
"""
