    nxt = set()
    for r in range(g.rows):
        for c in range(g.cols):
            n = g.neighbours(r, c)
            if (r, c) in g.alive and n in (2, 3):
                nxt.add((r, c))
            elif n == 3:
                nxt.add((r, c))
    return Grid(g.rows, g.cols, nxt)

